import{_ as e,o as r,c as d,a2 as o}from"./chunks/framework.BTjPRYTP.js";const u=JSON.parse('{"title":"Technology Stack","description":"","frontmatter":{},"headers":[],"relativePath":"guide/technology.md","filePath":"guide/technology.md"}'),a={name:"guide/technology.md"};function n(i,t,s,c,h,l){return r(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="technology-stack" tabindex="-1">Technology Stack <a class="header-anchor" href="#technology-stack" aria-label="Permalink to &quot;Technology Stack&quot;">​</a></h1><p>A comprehensive overview of the technologies powering TeslaSync, including rationale for each choice.</p><h2 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Technology</th><th>Version</th><th>Purpose</th><th>Why</th></tr></thead><tbody><tr><td><strong>Go</strong></td><td>1.22</td><td>Application language</td><td>Compiles to a single binary, low memory footprint (~30 MB RSS), excellent concurrency with goroutines, strong standard library for HTTP/JSON</td></tr><tr><td><strong>Chi</strong></td><td>v5</td><td>HTTP router</td><td>Lightweight, idiomatic Go, supports middleware chains, compatible with <code>net/http</code></td></tr><tr><td><strong>pgx</strong></td><td>v5</td><td>PostgreSQL driver</td><td>High-performance pure Go driver with connection pooling, prepared statements, batch queries, and native PostgreSQL type support</td></tr><tr><td><strong>zerolog</strong></td><td>latest</td><td>Structured logging</td><td>Zero-allocation JSON logger — no garbage collection pressure during high-throughput logging</td></tr><tr><td><strong>gobreaker</strong></td><td>latest</td><td>Circuit breaker</td><td>Sony&#39;s battle-tested implementation for protecting against cascading failures from the Tesla API</td></tr><tr><td><strong>httprate</strong></td><td>latest</td><td>Rate limiting</td><td>Configurable per-IP rate limiting middleware for Chi</td></tr></tbody></table><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Technology</th><th>Version</th><th>Purpose</th><th>Why</th></tr></thead><tbody><tr><td><strong>React</strong></td><td>18</td><td>UI framework</td><td>Component-based architecture, large ecosystem, concurrent rendering with Suspense</td></tr><tr><td><strong>TypeScript</strong></td><td>5.x</td><td>Type safety</td><td>Catches errors at compile time, improves IDE autocomplete, self-documenting code</td></tr><tr><td><strong>Vite</strong></td><td>5</td><td>Build tool</td><td>Lightning-fast HMR (~50ms), optimized production builds with tree-shaking, native ESM</td></tr><tr><td><strong>Tailwind CSS</strong></td><td>3.4</td><td>Utility styles</td><td>Rapid prototyping, consistent design system, tiny production CSS with purging</td></tr><tr><td><strong>Recharts</strong></td><td>2.12</td><td>Data visualization</td><td>Built on D3.js, composable React components, responsive charts out of the box</td></tr><tr><td><strong>TanStack Query</strong></td><td>5</td><td>Data fetching</td><td>Automatic caching, background refetching, stale-while-revalidate, request deduplication</td></tr><tr><td><strong>React Leaflet</strong></td><td>latest</td><td>Maps</td><td>Open-source map rendering for vehicle tracking, drive routes, and geofence visualization</td></tr><tr><td><strong>Framer Motion</strong></td><td>latest</td><td>Animations</td><td>Declarative animations with spring physics, layout transitions, gesture support</td></tr><tr><td><strong>Lucide</strong></td><td>latest</td><td>Icons</td><td>1000+ consistent, tree-shakeable SVG icons</td></tr></tbody></table><h2 id="data-layer" tabindex="-1">Data Layer <a class="header-anchor" href="#data-layer" aria-label="Permalink to &quot;Data Layer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Technology</th><th>Version</th><th>Purpose</th><th>Why</th></tr></thead><tbody><tr><td><strong>PostgreSQL</strong></td><td>17</td><td>Primary database</td><td>ACID compliance, JSONB support, native partitioning for time-series data, excellent query optimizer, mature ecosystem</td></tr><tr><td><strong>Redis</strong></td><td>7</td><td>Cache &amp; sessions</td><td>Sub-millisecond reads, LRU eviction, append-only persistence for durability</td></tr></tbody></table><h2 id="integration" tabindex="-1">Integration <a class="header-anchor" href="#integration" aria-label="Permalink to &quot;Integration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Technology</th><th>Version</th><th>Purpose</th><th>Why</th></tr></thead><tbody><tr><td><strong>Mosquitto</strong></td><td>2</td><td>MQTT broker</td><td>Lightweight pub/sub messaging for home automation integration (Home Assistant, Node-RED)</td></tr><tr><td><strong>Grafana</strong></td><td>10.4</td><td>Dashboards</td><td>16 pre-built dashboards with PostgreSQL datasource, alerting, and annotations</td></tr></tbody></table><h2 id="infrastructure" tabindex="-1">Infrastructure <a class="header-anchor" href="#infrastructure" aria-label="Permalink to &quot;Infrastructure&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Technology</th><th>Purpose</th><th>Why</th></tr></thead><tbody><tr><td><strong>Docker Compose</strong></td><td>Local/production deployment</td><td>Single-command deployment of all 6 services with health checks, resource limits, and volume persistence</td></tr><tr><td><strong>Nginx</strong></td><td>Frontend reverse proxy</td><td>Serves SPA with gzip compression, SPA fallback routing, and static asset caching</td></tr><tr><td><strong>GitHub Actions</strong></td><td>CI/CD</td><td>Automated builds, tests, and documentation deployment</td></tr><tr><td><strong>Prometheus</strong></td><td>Metrics collection</td><td>Exposes <code>/metrics</code> endpoint with Go runtime metrics, HTTP request metrics, and custom business metrics</td></tr></tbody></table><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Technology</th><th>Purpose</th><th>Why</th></tr></thead><tbody><tr><td><strong>VitePress</strong></td><td>Documentation site</td><td>Fast static site generator, Markdown + Vue components, built-in search, Mermaid diagram support</td></tr><tr><td><strong>Mermaid</strong></td><td>Architecture diagrams</td><td>Text-based diagram syntax that renders in VitePress and GitHub markdown</td></tr></tbody></table><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Implementation</th></tr></thead><tbody><tr><td><strong>HTTPS</strong></td><td>TLS termination at reverse proxy</td></tr><tr><td><strong>CORS</strong></td><td>Configurable origin whitelist</td></tr><tr><td><strong>Rate Limiting</strong></td><td>100 req/min per IP</td></tr><tr><td><strong>Security Headers</strong></td><td>X-Content-Type-Options, X-Frame-Options, HSTS, CSP</td></tr><tr><td><strong>OAuth2</strong></td><td>Tesla API authentication via authorization code flow</td></tr><tr><td><strong>Token Encryption</strong></td><td>Access/refresh tokens encrypted at rest</td></tr><tr><td><strong>Input Validation</strong></td><td>Request body validation on all mutation endpoints</td></tr></tbody></table><h2 id="performance-characteristics" tabindex="-1">Performance Characteristics <a class="header-anchor" href="#performance-characteristics" aria-label="Permalink to &quot;Performance Characteristics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Value</th></tr></thead><tbody><tr><td>Backend memory</td><td>~30 MB RSS (idle), ~50 MB under load</td></tr><tr><td>Frontend bundle</td><td>~350 KB gzipped (code-split per route)</td></tr><tr><td>API response time</td><td>&lt;10ms for cached, &lt;50ms for DB queries</td></tr><tr><td>SSE latency</td><td>&lt;100ms from poll to client update</td></tr><tr><td>Cold start</td><td>&lt;2s (Go binary + DB connection pool)</td></tr><tr><td>Docker image (backend)</td><td>~25 MB (scratch base)</td></tr><tr><td>Docker image (frontend)</td><td>~30 MB (Nginx alpine)</td></tr></tbody></table>',18)])])}const p=e(a,[["render",n]]);export{u as __pageData,p as default};
